/* Pixel Lap Timer Stylesheet */

[hidden] {
  display: none !important;
}

:root {
  --bg-color: #1a1c23;
  --card-bg: #282c37;
  --pixel-border: #0d0e15;
  --text-main: #f0f6f0;
  --text-muted: #8b9bb4;
  --accent-gold: #f4b41b;
  --accent-green: #38b764;
  --accent-red: #e43b44;
  --accent-cyan: #3b5dc9;
  --font-family: 'Courier New', Courier, monospace, monospace;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  font-family: var(--font-family);
}

body {
  background-color: var(--bg-color);
  color: var(--text-main);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 1rem;
  font-size: 16px;
  background-image:
    radial-gradient(#2d3345 15%, transparent 16%),
    radial-gradient(#2d3345 15%, transparent 16%);
  background-size: 16px 16px;
  background-position: 0 0, 8px 8px;
}

.app-container {
  width: 100%;
  max-width: 420px;
  min-width: 320px;
  background: var(--card-bg);
  border: 4px solid var(--pixel-border);
  box-shadow:
    8px 8px 0px 0px var(--pixel-border),
    inset -4px -4px 0px 0px rgba(0, 0, 0, 0.4),
    inset 4px 4px 0px 0px rgba(255, 255, 255, 0.1);
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.timer-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 3px dashed var(--text-muted);
  padding-bottom: 0.75rem;
}

.title {
  font-size: 1.25rem;
  font-weight: 800;
  letter-spacing: 1px;
  color: var(--accent-gold);
  text-shadow: 2px 2px 0 var(--pixel-border);
}

.pixel-art-runner {
  width: 16px;
  height: 16px;
  background: var(--accent-gold);
  box-shadow:
    4px 0 0 0 var(--accent-green),
    -4px 4px 0 0 var(--accent-red),
    0px 8px 0 0 var(--text-main);
}

.timer-display-box {
  background: #0f111a;
  border: 3px solid var(--pixel-border);
  padding: 1rem 0.5rem;
  text-align: center;
  position: relative;
  box-shadow: inset 0 0 8px rgba(0, 0, 0, 0.8);
}

.label-tag {
  position: absolute;
  top: 4px;
  left: 8px;
  font-size: 0.75rem;
  color: var(--text-muted);
  font-weight: 700;
}

.time-digits {
  font-size: 2.75rem;
  font-weight: 900;
  color: var(--accent-green);
  letter-spacing: 3px;
  text-shadow: 0 0 4px rgba(56, 183, 100, 0.6);
  padding: 0.25rem 0;
}

.controls {
  display: flex;
  gap: 0.75rem;
  justify-content: space-between;
}

.btn {
  flex: 1;
  font-size: 1rem;
  font-weight: 700;
  padding: 0.75rem 0.5rem;
  border: 3px solid var(--pixel-border);
  cursor: pointer;
  text-align: center;
  background: #414856;
  color: var(--text-main);
  position: relative;
  box-shadow: 0 4px 0 0 var(--pixel-border);
  transition: none;
  user-select: none;
}

.btn:hover:not(:disabled) {
  filter: brightness(1.15);
}

.btn:active:not(:disabled) {
  top: 4px;
  box-shadow: 0 0 0 0 var(--pixel-border);
}

.btn:focus-visible {
  outline: 3px solid var(--accent-gold);
  outline-offset: 2px;
}

.btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
  box-shadow: none;
  top: 4px;
}

.btn-primary {
  background-color: var(--accent-green);
  color: #0b2413;
}

.btn-primary.running {
  background-color: var(--accent-red);
  color: #ffffff;
}

.btn-secondary {
  background-color: var(--accent-cyan);
  color: #ffffff;
}

.btn-danger {
  background-color: #62697a;
  color: #ffffff;
}

.laps-card {
  background: #1e212b;
  border: 3px solid var(--pixel-border);
  padding: 0.75rem;
  display: flex;
  flex-direction: column;
  max-height: 220px;
}

.laps-header {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  font-weight: 700;
  font-size: 0.85rem;
  color: var(--text-muted);
  padding-bottom: 0.5rem;
  border-bottom: 2px solid var(--pixel-border);
  text-align: center;
}

.laps-list {
  list-style: none;
  overflow-y: auto;
  padding: 0;
  margin-top: 0.25rem;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.laps-list li {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  padding: 0.5rem 0.25rem;
  font-size: 0.95rem;
  font-weight: 600;
  border-bottom: 1px dashed #323745;
  text-align: center;
}

.laps-list li.empty-laps {
  display: block;
  color: var(--text-muted);
  font-style: italic;
  padding: 1rem 0;
  border: none;
}

.laps-list li.fastest-lap {
  background-color: rgba(244, 180, 27, 0.15);
  border: 2px solid var(--accent-gold);
  color: var(--accent-gold);
  font-weight: 800;
  position: relative;
}

.laps-list li.fastest-lap::before {
  content: '★ ';
}

@media (max-width: 360px) {
  .app-container {
    padding: 1rem;
  }
  .time-digits {
    font-size: 2.25rem;
  }
  .btn {
    font-size: 0.875rem;
    padding: 0.6rem 0.25rem;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  let startTime = 0;
  let elapsedTime = 0;
  let timerInterval = null;
  let laps = [];
  let lastLapTime = 0;

  const displayEl = document.getElementById('display');
  const startStopBtn = document.getElementById('startStopBtn');
  const lapBtn = document.getElementById('lapBtn');
  const resetBtn = document.getElementById('resetBtn');
  const lapsList = document.getElementById('lapsList');
  const emptyNotice = document.getElementById('emptyNotice');

  function formatTime(ms) {
    const totalTenths = Math.floor(ms / 100);
    const tenths = totalTenths % 10;
    const totalSeconds = Math.floor(totalTenths / 10);
    const seconds = totalSeconds % 60;
    const minutes = Math.floor(totalSeconds / 60);

    const mm = String(minutes).padStart(2, '0');
    const ss = String(seconds).padStart(2, '0');
    return `${mm}:${ss}.${tenths}`;
  }

  function updateDisplay() {
    const now = Date.now();
    const currentElapsed = elapsedTime + (timerInterval ? now - startTime : 0);
    displayEl.textContent = formatTime(currentElapsed);
  }

  function renderLaps() {
    if (laps.length === 0) {
      if (emptyNotice) {
        emptyNotice.hidden = false;
      }
      lapsList.innerHTML = '';
      const emptyLi = document.createElement('li');
      emptyLi.className = 'empty-laps';
      emptyLi.id = 'emptyNotice';
      emptyLi.textContent = 'No laps recorded';
      lapsList.appendChild(emptyLi);
      return;
    }

    // Find minimum lap duration for fastest highlight
    let minDuration = Infinity;
    laps.forEach(lap => {
      if (lap.duration < minDuration) {
        minDuration = lap.duration;
      }
    });

    lapsList.innerHTML = '';

    // Newest lap first (array is traversed in reverse order)
    for (let i = laps.length - 1; i >= 0; i--) {
      const lap = laps[i];
      const li = document.createElement('li');
      const isFastest = laps.length > 1 && lap.duration === minDuration;

      if (isFastest) {
        li.classList.add('fastest-lap');
      }

      const lapNumSpan = document.createElement('span');
      lapNumSpan.textContent = `Lap ${lap.number}`;

      const splitSpan = document.createElement('span');
      splitSpan.textContent = formatTime(lap.duration);

      const totalSpan = document.createElement('span');
      totalSpan.textContent = formatTime(lap.totalTime);

      li.appendChild(lapNumSpan);
      li.appendChild(splitSpan);
      li.appendChild(totalSpan);

      lapsList.appendChild(li);
    }
  }

  function toggleStartStop() {
    if (timerInterval) {
      // Stopping the timer
      elapsedTime += Date.now() - startTime;
      clearInterval(timerInterval);
      timerInterval = null;
      startStopBtn.textContent = 'START';
      startStopBtn.classList.remove('running');
      lapBtn.disabled = true;
    } else {
      // Starting the timer
      startTime = Date.now();
      timerInterval = setInterval(updateDisplay, 30);
      startStopBtn.textContent = 'STOP';
      startStopBtn.classList.add('running');
      lapBtn.disabled = false;
      resetBtn.disabled = false;
    }
    updateDisplay();
  }

  function recordLap() {
    const totalTime = elapsedTime + (timerInterval ? Date.now() - startTime : 0);
    const lapDuration = totalTime - lastLapTime;
    lastLapTime = totalTime;

    const lapNumber = laps.length + 1;
    laps.push({
      number: lapNumber,
      duration: lapDuration,
      totalTime: totalTime
    });

    renderLaps();
  }

  function resetTimer() {
    if (timerInterval) {
      clearInterval(timerInterval);
      timerInterval = null;
    }
    startTime = 0;
    elapsedTime = 0;
    lastLapTime = 0;
    laps = [];

    displayEl.textContent = '00:00.0';
    startStopBtn.textContent = 'START';
    startStopBtn.classList.remove('running');
    lapBtn.disabled = true;
    resetBtn.disabled = true;

    renderLaps();
  }

  startStopBtn.addEventListener('click', toggleStartStop);
  lapBtn.addEventListener('click', recordLap);
  resetBtn.addEventListener('click', resetTimer);

  // Keyboard shortcuts
  window.addEventListener('keydown', (e) => {
    if (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA') {
      return;
    }
    if (e.code === 'Space') {
      e.preventDefault();
      toggleStartStop();
    } else if (e.code === 'KeyL' && !lapBtn.disabled) {
      e.preventDefault();
      recordLap();
    } else if (e.code === 'KeyR' && !resetBtn.disabled) {
      e.preventDefault();
      resetTimer();
    }
  });
});
